import Yoga from 'yoga-layout';
const parent = Yoga.Node.create();
parent.setWidth(15);
parent.setFlexDirection(Yoga.FLEX_DIRECTION_ROW);
parent.setFlexWrap(Yoga.WRAP_NO_WRAP);
parent.setFlexGrow(0);
parent.setFlexShrink(1);
parent.setGap(Yoga.GUTTER_COLUMN, 1);
parent.setGap(Yoga.GUTTER_ROW, 1);

const makeBox = () => {
  const box = Yoga.Node.create();
  box.setFlexDirection(Yoga.FLEX_DIRECTION_ROW);
  box.setFlexWrap(Yoga.WRAP_NO_WRAP);
  box.setFlexGrow(0);
  box.setFlexShrink(1);
  const text = Yoga.Node.create();
  text.setMeasureFunc(() => ({width: 1, height: 1}));
  text.setFlexGrow(0);
  text.setFlexShrink(1);
  text.setFlexDirection(Yoga.FLEX_DIRECTION_ROW);
  box.insertChild(text, 0);
  return box;
};

const boxes = [makeBox(), makeBox(), makeBox()];
boxes.forEach(b => parent.insertChild(b, parent.getChildCount()));
// Reset like applyGridLayout does
boxes.forEach(b => { b.setFlexShrink(0); b.setFlexGrow(0); b.setPositionType(Yoga.POSITION_TYPE_RELATIVE); b.setPosition(Yoga.EDGE_LEFT,0); b.setPosition(Yoga.EDGE_TOP,0); b.setWidthAuto(); b.setHeightAuto(); });
parent.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
console.log('relative', boxes.map(b => [b.getComputedWidth(), b.getComputedHeight()]));
boxes.forEach((b, i) => {
  b.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
  b.setPosition(Yoga.EDGE_LEFT, i * 6);
  b.setPosition(Yoga.EDGE_TOP, 0);
  b.setWidth(5);
  b.setHeight(1);
});
parent.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
console.log('after set 5x1', boxes.map(b => [b.getComputedWidth(), b.getComputedHeight(), b.getWidth().value, b.getHeight().value]));

